def find_order(num_courses, prerequisites):
    adj = defaultdict(list)
    for a, b in prerequisites:
        adj[b].append(a)
    color, post = [0] * num_courses, []

    def dfs(u):
        color[u] = 1
        for v in adj[u]:
            if color[v] == 1 or (color[v] == 0 and not dfs(v)):
                return False
        color[u] = 2
        post.append(u)
        return True

    for u in range(num_courses):
        if color[u] == 0 and not dfs(u):
            return []
    return post[::-1]

def find_order(num_courses, prerequisites):
    adj, indeg = defaultdict(list), [0] * num_courses
    for a, b in prerequisites:
        adj[b].append(a)
        indeg[a] += 1
    queue = deque(u for u in range(num_courses) if indeg[u] == 0)
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return order if len(order) == num_courses else []
